import sys
from collections import Counter
import math

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        k = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    def get_core(x, k):
        core = 1
        temp = x
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    count += 1
                    temp //= p
                rem = count % k
                if rem > 0:
                    core *= (p ** rem)
            p += 1
        if temp > 1:
            core *= temp
        return core

    def get_needed(core, k):
        needed = 1
        p = 2
        temp = core
        while p * p <= temp:
            if temp % p != 0:
                continue
            count = 0
            while temp % p == 0:
                count += 1
                temp //= p
            rem = count % k
            if rem > 0:
                needed *= (p ** (k - rem))
            else:
                needed *= (p ** k)
            p += 1
        if temp > 1: 
            needed *= (temp ** k)
        return needed

    freq = Counter()
    count = 0
    max_val = 100000
    limit = max_val * max_val

    for x in a:
        core_x = get_core(x, k)
        needed = get_needed(core_x, k)

        if needed <= limit:
            if needed in freq:
                count += freq[needed]

        freq[core_x] += 1

    print(count)

if __name__ == "__main__":
    main()
